window.docContents[8].resolve({"/Foundations/#PDEAtlas--Foundations--PDE-Problems-and-Differential-Operators--Coordinate-derivatives-and-vector-operators":{"contents":"PDE formulas are written with gradients, divergences, Laplacians, and\ntransport derivatives, while Mathlib's calculus is organized around the\nFréchet derivative. We set up the dictionary between those two\nlanguages. Coordinate derivatives are obtained by evaluating the Fréchet\nderivative on Euclidean basis vectors; the vector operators are then assembled\nfrom those coordinates.\n\n\n\n\n\n","context":"PDEAtlas\u0009Foundations\u0009PDE Problems and Differential Operators","header":"3.2.2. Coordinate derivatives and vector operators","id":"/Foundations/#PDEAtlas--Foundations--PDE-Problems-and-Differential-Operators--Coordinate-derivatives-and-vector-operators"},"/Representation-Formulas___-Variational-Principles___-and-Fixed-Points/#PDEAtlas--Representation-Formulas___-Variational-Principles___-and-Fixed-Points--Representing-Solutions--Explicit-Representations-and-Transform-Methods--Cole___Hopf-Transformation":{"contents":"\n\n","context":"PDEAtlas\u0009Representation Formulas, Variational Principles, and Fixed Points\u0009Representing Solutions\u0009Explicit Representations and Transform Methods","header":"9.2.1.5. Cole–Hopf Transformation","id":"/Representation-Formulas___-Variational-Principles___-and-Fixed-Points/#PDEAtlas--Representation-Formulas___-Variational-Principles___-and-Fixed-Points--Representing-Solutions--Explicit-Representations-and-Transform-Methods--Cole___Hopf-Transformation"}});